<h1><?= e($astrologer['name'] ?? 'Astrologer Profile') ?></h1><?php if(!$astrologer): ?><p>Astrologer not found.</p><?php else: ?><p><?= e($astrologer['description'] ?? '') ?></p><form method="get"><label>Date <input type="date" name="date" value="<?= e($date) ?>"></label><button>Check slots</button></form><h2>Available slots</h2><?php if(!$slots): ?><p>No slots available for this date.</p><?php endif; ?><div class="slot-grid"><?php foreach($slots as $slot): ?><form method="post" action="/appointments/book" class="slot-card"><input type="hidden" name="astrologer_slug" value="<?= e($astrologer['slug']) ?>"><input type="hidden" name="date" value="<?= e($date) ?>"><input type="hidden" name="time" value="<?= e($slot) ?>"><label>Mode<select name="mode"><option value="in-person">In person</option><option value="remote">Remote</option></select></label><button><?= e($slot) ?> Book</button></form><?php endforeach; ?></div><?php endif; ?>
